1. useFilters 커스텀 훅 생성 (/src/hooks/useFilters.ts):
   ```typescript
   export const useFilters = () => {
     const [filters, setFilters] = useState({
       completed: 'all', // 'all' | 'completed' | 'active'
       priority: 'all', // 'all' | 'high' | 'medium' | 'low'
       tags: [] as string[],
       dueDate: 'all', // 'all' | 'overdue' | 'today' | 'week'
       searchText: ''
     });

     // localStorage에 필터 상태 저장/복원
     useEffect(() => {
       const saved = localStorage.getItem('todoFilters');
       if (saved) setFilters(JSON.parse(saved));
     }, []);

     useEffect(() => {
       localStorage.setItem('todoFilters', JSON.stringify(filters));
     }, [filters]);

     return { filters, setFilters };
   };
   ```
2. useSort 커스텀 훅 생성:
