   - 정렬 방향: asc, desc
3. 필터링 로직 구현 (/src/lib/filterTodos.ts):
   ```typescript
   export const filterTodos = (todos: Todo[], filters: Filters) => {
     return todos.filter(todo => {
       // 완료 상태 필터
       if (filters.completed === 'completed' && !todo.completed) return false;
       if (filters.completed === 'active' && todo.completed) return false;

       // 우선순위 필터
       if (filters.priority !== 'all' && todo.priority !== filters.priority) return false;

       // 태그 필터
       if (filters.tags.length > 0 && !filters.tags.some(tag => todo.tags.includes(tag))) return false;

       // 마감일 필터
       // ...

       // 검색 텍스트
       if (filters.searchText && !todo.title.toLowerCase().includes(filters.searchText.toLowerCase())) return false;

       return true;
     });
   };
   ```
